Here is the commit message:
net: fix sparc64 compilation of sock_gettstamp

net/core/sock.c: In function 'sock_gettstamp':
net/core/sock.c:3007:23: error: expected '}' before ';' token
    .tv_sec = ts.tv_sec;
                       ^
net/core/sock.c:3011:4: error: expected ')' before 'return'
    return -EFAULT;
    ^~~~~~
net/core/sock.c:3013:2: error: expected expression before '}' token
  }
  ^

Fixes: c7cbdbf29f48 ("net: rework SIOCGSTAMP ioctl handling")
Signed-off-by: Stephen Rothwell <sfr@canb.auug.org.au>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The bug was caused by incorrect syntax in the initialization of the `__kernel_old_timeval` structure, specifically the use of a semicolon instead of a comma, which led to compilation errors. Additionally, a missing closing parenthesis in the `copy_to_user` function call contributed to the compilation failure. These issues prevented the function from being properly defined and compiled for the sparc64 architecture.

Here is the patch:

 int sock_gettstamp(struct socket *sock, void __user *userstamp,
 		   bool timeval, bool time32)
 {
 	struct sock *sk = sock->sk;
 	struct timespec64 ts;

 	sock_enable_timestamp(sk, SOCK_TIMESTAMP);
 	ts = ktime_to_timespec64(sock_read_timestamp(sk));
 	if (ts.tv_sec == -1)
 		return -ENOENT;
 	if (ts.tv_sec == 0) {
 		ktime_t kt = ktime_get_real();
 		sock_write_timestamp(sk, kt);;
 		ts = ktime_to_timespec64(kt);
 	}

 	if (timeval)
 		ts.tv_nsec /= 1000;

 #ifdef CONFIG_COMPAT_32BIT_TIME
 	if (time32)
 		return put_old_timespec32(&ts, userstamp);
 #endif
 #ifdef CONFIG_SPARC64
 	/* beware of padding in sparc64 timeval */
 	if (timeval && !in_compat_syscall()) {
 		struct __kernel_old_timeval __user tv = {
-			.tv_sec = ts.tv_sec;
-			.tv_usec = ts.tv_nsec;
+			.tv_sec = ts.tv_sec,
+			.tv_usec = ts.tv_nsec,
 		};
-		if (copy_to_user(userstamp, &tv, sizeof(tv))
+		if (copy_to_user(userstamp, &tv, sizeof(tv)))
 			return -EFAULT;
 		return 0;
 	}
 #endif
 	return put_timespec64(&ts, userstamp);
 }
 EXPORT_SYMBOL(sock_gettstamp);


